-- Phase 3A: private complete call evidence only. No generation, chart write or processing activation.
create table public.clinical_call_policies(version integer primary key check(version>0),status text not null check(status in('draft','approved')),consent_text text not null,retention_text text not null,reviewed_by uuid,reviewed_at timestamptz,created_at timestamptz not null default clock_timestamp(),check((status='approved'and reviewed_by is not null and reviewed_at is not null)or(status='draft'and reviewed_by is null and reviewed_at is null)));
insert into public.clinical_call_policies values(1,'draft','Susan must approve authorized household-call processing and the private full-call versus reviewed chart distinction.','Draft: retain complete observed transcript evidence and capture provenance; practice retention approval pending.',null,null,clock_timestamp());
create table public.clinical_call_policy_actions(id uuid primary key,actor_id uuid not null,request jsonb,policy jsonb,cancelled boolean not null default false,created_at timestamptz not null default clock_timestamp());
create table public.clinical_call_capture_actions(id uuid primary key,actor_id uuid not null,session_id uuid not null,request jsonb,binding jsonb,state text not null check(state in('pending','capturing','completed','failed','cancelled')),source_id uuid,error_code text,lease_until timestamptz,result_hash text,created_at timestamptz not null default clock_timestamp(),finished_at timestamptz);
create table public.clinical_call_sources(id uuid primary key,capture_id uuid not null unique,actor_id uuid not null,pet_id uuid not null,encounter_id uuid not null,client_id uuid not null,conversation_id uuid not null,call_uuid text not null,call_id text not null,policy_version integer not null,context jsonb not null,document jsonb not null,sha256 text not null check(sha256~'^[a-f0-9]{64}$'),created_at timestamptz not null default clock_timestamp());
create index clinical_call_sources_patient on public.clinical_call_sources(pet_id,created_at desc,id desc);
do $$declare t text;begin foreach t in array array['clinical_call_policies','clinical_call_policy_actions','clinical_call_capture_actions','clinical_call_sources']loop execute format('alter table public.%I enable row level security',t);execute format('revoke all on public.%I from public,anon,authenticated,service_role',t);end loop;end $$;
create trigger immutable_call_policy before update or delete on public.clinical_call_policies for each row execute function public.guard_inquiry_history();
create trigger immutable_call_source before update or delete on public.clinical_call_sources for each row execute function public.guard_inquiry_history();
create function public.clinical_call_actor(p_actor_id uuid)returns uuid language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform public.clinical_dictation_actor(p_actor_id);perform public.clinical_audio_worker_actor(p_actor_id,public.next_visit_review_session());if not public.has_role(p_actor_id,'ADMIN')then raise exception 'Current administrator required'using errcode='PT403';end if;return p_actor_id;end $$;
create function public.clinical_call_worker_actor(p_actor uuid,p_session uuid)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.clinical_audio_worker_actor(p_actor,p_session);if not public.has_role(p_actor,'ADMIN')then raise exception 'Original administrator authority lost'using errcode='PT403';end if;end $$;
create function public.clinical_call_current_policy()returns jsonb language sql security definer set search_path=public,pg_temp as $$select to_jsonb(p)from clinical_call_policies p order by version desc limit 1$$;
create function public.read_clinical_call_policy(p_actor_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin perform public.clinical_call_actor(p_actor_id);return public.clinical_call_current_policy();end $$;
create function public.save_clinical_call_policy(p_actor_id uuid,p_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_policy_actions;p jsonb;r jsonb;begin
 perform public.clinical_call_actor(p_actor_id);perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform public.clinical_call_actor(p_actor_id);
 select *into a from clinical_call_policy_actions where id=p_id;if found then if a.actor_id<>p_actor_id or a.request is distinct from p_request or a.cancelled then raise exception 'Policy action conflict'using errcode='PT409';end if;return a.policy;end if;
 perform public.clinical_recap_keys(p_request,array['expected_version','status','consent_text','retention_text','attest_reviewed']);p:=public.clinical_call_current_policy();
 perform public.clinical_recap_integer(p_request->'expected_version',1,2147483646);
 if(p_request->>'expected_version')::integer<>(p->>'version')::integer or (p_request->>'status'is null or p_request->>'status'not in('draft','approved'))or not coalesce(public.clinical_recap_text(p_request->'consent_text',4000),false)or not coalesce(public.clinical_recap_text(p_request->'retention_text',2000),false)or jsonb_typeof(p_request->'attest_reviewed')is distinct from'boolean'or(p_request->>'status'='approved'and p_request->'attest_reviewed'<>'true'::jsonb)then raise exception 'Exact reviewed policy request required'using errcode='PT422';end if;
 insert into clinical_call_policies(version,status,consent_text,retention_text,reviewed_by,reviewed_at)values((p->>'version')::integer+1,p_request->>'status',p_request->>'consent_text',p_request->>'retention_text',case when p_request->>'status'='approved'then p_actor_id end,case when p_request->>'status'='approved'then clock_timestamp()end)returning to_jsonb(clinical_call_policies.*)into r;
 insert into clinical_call_policy_actions(id,actor_id,request,policy)values(p_id,p_actor_id,p_request,r);return r;end $$;
create function public.recover_clinical_call_policy(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_policy_actions;begin perform public.clinical_call_actor(p_actor_id);select *into a from clinical_call_policy_actions where id=p_id;if not found then return null;end if;if a.actor_id<>p_actor_id then raise exception 'Forbidden'using errcode='PT403';end if;return a.policy;end $$;
create function public.cancel_clinical_call_policy(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_policy_actions;begin perform public.clinical_call_actor(p_actor_id);perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform public.clinical_call_actor(p_actor_id);select *into a from clinical_call_policy_actions where id=p_id;if found then if a.actor_id<>p_actor_id then raise exception 'Forbidden'using errcode='PT403';end if;return jsonb_build_object('cancelled',a.cancelled);end if;insert into clinical_call_policy_actions(id,actor_id,cancelled)values(p_id,p_actor_id,true);return jsonb_build_object('cancelled',true);end $$;
-- All admission checks lock actual canonical rows; repeat authority after these potentially blocking reads.
create function public.clinical_call_binding(p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare patient pets;enc clinical_encounters;i communication_inbound;c cloudtalk_calls;thread conversations;msg messages;k text;begin
 perform public.clinical_recap_keys(p_request,array['pet_id','expected_pet_version','encounter_id','expected_encounter_version','inbound_id','expected_inbound_version','policy_version','attest_authorized']);
 foreach k in array array['pet_id','encounter_id','inbound_id']loop perform public.clinical_recap_uuid(p_request->k);end loop;
 foreach k in array array['expected_pet_version','expected_encounter_version','expected_inbound_version','policy_version']loop perform public.clinical_recap_integer(p_request->k,1,2147483646);end loop;
 if p_request->'attest_authorized'is distinct from'true'::jsonb then raise exception 'Authorization attestation required'using errcode='PT422';end if;
 select *into enc from clinical_encounters where id=(p_request->>'encounter_id')::uuid for share;select *into patient from pets where id=(p_request->>'pet_id')::uuid for share;
 if enc.id is null or patient.id is null or enc.pet_id<>patient.id or enc.status<>'draft'or enc.version<>(p_request->>'expected_encounter_version')::integer or patient.version<>(p_request->>'expected_pet_version')::integer or patient.archived_at is not null or patient.deceased_at is not null then raise exception 'Exact active patient and unsigned destination required'using errcode='PT409';end if;
 select *into i from communication_inbound where id=(p_request->>'inbound_id')::uuid for share;
 if i.id is null or i.provider<>'cloudtalk'or i.resource_id not like'call:%'or i.version<>(p_request->>'expected_inbound_version')::integer or i.client_id is distinct from patient.client_id or i.message_id is null or i.conversation_id is null then raise exception 'Exact assigned household call required'using errcode='PT409';end if;
 select *into c from cloudtalk_calls where call_uuid=substring(i.resource_id from 6)for share;select *into thread from conversations where id=i.conversation_id for share;select *into msg from messages where id=i.message_id for share;
 if c.call_uuid is null or not c.trusted_number or not c.transcript_ready or c.ended_at is null or c.call_id is null or c.call_id!~'^[1-9][0-9]{0,15}$'or c.call_id::numeric>9007199254740991 or thread.client_id is distinct from patient.client_id or msg.conversation_id is distinct from i.conversation_id or msg.provider is distinct from'cloudtalk'or msg.provider_message_id is distinct from i.resource_id then raise exception 'Trusted completed call projection required'using errcode='PT409';end if;
 return jsonb_build_object('client_id',patient.client_id,'conversation_id',i.conversation_id,'message_id',i.message_id,'call_uuid',c.call_uuid,'call_id',c.call_id,'call_started_at',case when c.started_at is not null then public.clinical_recap_timestamp(c.started_at)end,'call_ended_at',public.clinical_recap_timestamp(c.ended_at),'call_last_event_at',public.clinical_recap_timestamp(c.last_event_at),'inbound_version',i.version);
end $$;
create function public.clinical_call_capture_guard(a public.clinical_call_capture_actions)returns void language plpgsql security definer set search_path=public,pg_temp as $$declare p jsonb;b jsonb;begin
 perform public.clinical_call_worker_actor(a.actor_id,a.session_id);p:=public.clinical_call_current_policy();if p->>'status'is distinct from'approved'or(p->>'version')::integer is distinct from(a.request->>'policy_version')::integer then raise exception 'Call-source policy changed or awaits approval'using errcode='PT403';end if;
 b:=public.clinical_call_binding(a.request);if b is distinct from a.binding then raise exception 'Call source assignment changed'using errcode='PT409';end if;perform public.clinical_call_worker_actor(a.actor_id,a.session_id);
end $$;
create function public.clinical_call_source_access(s public.clinical_call_sources)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 perform 1 from pets p join communication_inbound i on i.client_id=p.client_id join conversations c on c.id=i.conversation_id and c.client_id=p.client_id join messages m on m.id=i.message_id and m.conversation_id=c.id join cloudtalk_calls provider on provider.call_uuid=s.call_uuid and provider.call_id=s.call_id and provider.trusted_number where p.id=s.pet_id and p.client_id=s.client_id and i.provider='cloudtalk'and i.resource_id='call:'||s.call_uuid and i.conversation_id=s.conversation_id and m.provider='cloudtalk'and m.provider_message_id=i.resource_id for share of p,i,c,m,provider;
 if not found then raise exception 'Source household association changed'using errcode='PT403';end if;
end $$;
create function public.clinical_call_action_view(a public.clinical_call_capture_actions)returns jsonb language sql stable security definer set search_path=public,pg_temp as $$select to_jsonb(a)-array['session_id','binding','result_hash']$$;
create function public.read_clinical_call_capture(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_capture_actions;s clinical_call_sources;begin
 perform public.clinical_call_actor(p_actor_id);perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));perform public.clinical_call_actor(p_actor_id);select *into a from clinical_call_capture_actions where id=p_id for update;if not found then raise exception 'Capture missing'using errcode='PT404';end if;if a.actor_id<>p_actor_id then raise exception 'Forbidden'using errcode='PT403';end if;
 if a.state='capturing'and(a.lease_until is null or a.lease_until<=clock_timestamp())then update clinical_call_capture_actions set state='failed',error_code='capture_unconfirmed',finished_at=clock_timestamp()where id=p_id returning *into a;end if;
 if a.source_id is not null then select *into s from clinical_call_sources where id=a.source_id;perform public.clinical_call_source_access(s);end if;perform public.clinical_call_actor(p_actor_id);
 return jsonb_build_object('action',public.clinical_call_action_view(a),'source',case when s.id is not null then to_jsonb(s)end,'policy',public.clinical_call_current_policy());end $$;
create function public.reserve_clinical_call_capture(p_actor_id uuid,p_id uuid,p_request jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_capture_actions;b jsonb;p jsonb;begin
 perform public.clinical_call_actor(p_actor_id);perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));perform public.clinical_call_actor(p_actor_id);
 select *into a from clinical_call_capture_actions where id=p_id;if found then if a.actor_id<>p_actor_id or a.request is distinct from p_request or a.state='cancelled'then raise exception 'Capture intent conflict'using errcode='PT409';end if;return public.read_clinical_call_capture(p_actor_id,p_id);end if;
 b:=public.clinical_call_binding(p_request);p:=public.clinical_call_current_policy();if p->>'status'is distinct from'approved'or(p->>'version')::integer is distinct from(p_request->>'policy_version')::integer then raise exception 'Call-source policy approval required'using errcode='PT403';end if;perform public.clinical_call_actor(p_actor_id);
 insert into clinical_call_capture_actions(id,actor_id,session_id,request,binding,state)values(p_id,p_actor_id,public.next_visit_review_session(),p_request,b,'pending');return public.read_clinical_call_capture(p_actor_id,p_id);end $$;
create function public.cancel_clinical_call_capture(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_capture_actions;begin
 perform public.clinical_call_actor(p_actor_id);perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));perform public.clinical_call_actor(p_actor_id);select *into a from clinical_call_capture_actions where id=p_id for update;
 if found then if a.actor_id<>p_actor_id then raise exception 'Forbidden'using errcode='PT403';end if;if a.state<>'pending'then return jsonb_build_object('cancelled',a.state='cancelled');end if;update clinical_call_capture_actions set state='cancelled',finished_at=clock_timestamp()where id=p_id;
 else insert into clinical_call_capture_actions(id,actor_id,session_id,state,finished_at)values(p_id,p_actor_id,public.next_visit_review_session(),'cancelled',clock_timestamp());end if;return jsonb_build_object('cancelled',true);end $$;
create function public.dispatch_clinical_call_capture(p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_capture_actions;begin
 perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));select *into a from clinical_call_capture_actions where id=p_id for update;if not found then raise exception 'Capture missing'using errcode='PT404';end if;if a.state<>'pending'then return null;end if;perform public.clinical_call_capture_guard(a);
 update clinical_call_capture_actions set state='capturing',lease_until=clock_timestamp()+interval'3 minutes'where id=p_id returning *into a;return jsonb_build_object('action',public.clinical_call_action_view(a),'provider_call_id',a.binding->>'call_id');end $$;
create function public.clinical_call_validate_document(d jsonb,p_call_id text)returns void language plpgsql immutable set search_path=public,pg_temp as $$declare s jsonb;pg jsonb;caller jsonb;labels text[]:=array[]::text[];n integer:=0;off integer:=0;last_start numeric:=-1;pass integer;expected_offset integer;total integer;page_count integer:=0;v text;piece text;begin
 perform public.clinical_recap_keys(d,array['contract_version','provider_schema_version','completeness','call_id','language','callers','segments','projection','pages','captured_from','captured_until']);
 if octet_length(convert_to(d::text,'UTF8'))>2000000 or d->>'contract_version'is distinct from'clinical-call-source-v1'or d->>'provider_schema_version'is distinct from'cloudtalk-ci-transcription-v1'or d->>'completeness'is distinct from'observed_two_pass'or jsonb_typeof(d->'call_id')is distinct from'string'or d->>'call_id'is distinct from p_call_id or not coalesce(public.clinical_recap_text(d->'language',80),false)or not coalesce(public.clinical_recap_text(d->'projection',60000),false)or octet_length(convert_to(d->>'projection','UTF8'))>240000 or jsonb_typeof(d->'callers')is distinct from'array'or jsonb_array_length(d->'callers')not between 1 and 50 or jsonb_typeof(d->'segments')is distinct from'array'or jsonb_array_length(d->'segments')not between 1 and 1000 or jsonb_typeof(d->'pages')is distinct from'array'or jsonb_array_length(d->'pages')not between 2 and 20 then raise exception 'Bounded complete call source required'using errcode='PT422';end if;
 if jsonb_typeof(d->'captured_from')is distinct from'string'or jsonb_typeof(d->'captured_until')is distinct from'string'or d->>'captured_from'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$'or d->>'captured_until'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?(Z|[+-][0-9]{2}:[0-9]{2})$'or(d->>'captured_until')::timestamptz<(d->>'captured_from')::timestamptz or(d->>'captured_until')::timestamptz-(d->>'captured_from')::timestamptz>interval'120 seconds'then raise exception 'Bounded capture times required'using errcode='PT422';end if;
 for caller in select value from jsonb_array_elements(d->'callers')loop
  perform public.clinical_recap_keys(caller,array['type','id','localIdentifier']);
  if caller->>'type'is null or caller->>'type'not in('agent','contact')or not coalesce(public.clinical_recap_text(caller->'localIdentifier',100),false)or caller->>'localIdentifier'=any(labels)or not(caller->'id'='null'::jsonb or(jsonb_typeof(caller->'id')='number'and caller->>'id'~'^-?[0-9]+$'and abs((caller->>'id')::numeric)<=9007199254740991))then raise exception 'Original unique caller labels required'using errcode='PT422';end if;labels:=array_append(labels,caller->>'localIdentifier');
 end loop;
 for s in select value from jsonb_array_elements(d->'segments')loop
  n:=n+1;perform public.clinical_recap_keys(s,array['ordinal','start','end','caller','text','text_sha256','projection_from','projection_to']);
  if public.clinical_recap_integer(s->'ordinal',1,1000)<>n or jsonb_typeof(s->'start')is distinct from'number'or jsonb_typeof(s->'end')is distinct from'number'or(s->>'start')::numeric<last_start or(s->>'start')::numeric<0 or(s->>'end')::numeric<(s->>'start')::numeric or not coalesce(public.clinical_recap_text(s->'caller',100),false)or not(s->>'caller'=any(labels))or not coalesce(public.clinical_recap_text(s->'text',60000),false)or s->>'text_sha256'is distinct from encode(extensions.digest(convert_to(s->>'text','UTF8'),'sha256'),'hex')or public.clinical_recap_integer(s->'projection_from',0,60000)<>off or public.clinical_recap_integer(s->'projection_to',1,60000)<=off then raise exception 'Exact ordered segment evidence required'using errcode='PT422';end if;
  -- Segments preserve original overlap/equal starts. Projection offsets count UTF16, as the note engine does.
  piece:='[#'||lpad(n::text,4,'0')||' caller='||(s->'caller')::text||']'||chr(10)||(s->>'text')||chr(10);
  if (s->>'projection_to')::integer<>off+public.clinical_note_text_length(piece)then raise exception 'Exact segment projection offsets required'using errcode='PT422';end if;
  off:=(s->>'projection_to')::integer;last_start:=(s->>'start')::numeric;
 end loop;
 -- Rebuild projection from structured evidence, never accept unrelated text under a valid segment hash.
 select string_agg('[#'||lpad((x->>'ordinal'),4,'0')||' caller='||(x->'caller')::text||']'||chr(10)||(x->>'text')||chr(10),''order by ord)into v from jsonb_array_elements(d->'segments')with ordinality t(x,ord);
 if v is distinct from d->>'projection'or off<>public.clinical_note_text_length(v)then raise exception 'Exact source projection required'using errcode='PT422';end if;
 for pg in select value from jsonb_array_elements(d->'pages')loop perform public.clinical_recap_integer(pg->'pass',1,2);end loop;
 -- Both passes must cover the same declared count without gaps, short pages or changed normalized-page hashes.
 for pass in 1..2 loop expected_offset:=0;page_count:=0;
  for pg in select value from jsonb_array_elements(d->'pages')where(value->>'pass')::integer=pass loop
   page_count:=page_count+1;perform public.clinical_recap_keys(pg,array['pass','offset','limit','total','count','sha256','retrieved_at','normalized_json']);
   if public.clinical_recap_integer(pg->'pass',1,2)<>pass or public.clinical_recap_integer(pg->'offset',0,1000)<>expected_offset or public.clinical_recap_integer(pg->'limit',100,100)<>100 or public.clinical_recap_integer(pg->'total',1,1000)<>n or public.clinical_recap_integer(pg->'count',1,100)<>least(100,n-expected_offset)or jsonb_typeof(pg->'sha256')is distinct from'string'or pg->>'sha256'!~'^[a-f0-9]{64}$'or not coalesce(public.clinical_recap_text(pg->'normalized_json',512000),false)or octet_length(convert_to(pg->>'normalized_json','UTF8'))>512000 or pg->>'sha256'is distinct from encode(extensions.digest(convert_to(pg->>'normalized_json','UTF8'),'sha256'),'hex')or(pg->>'normalized_json')::jsonb is distinct from jsonb_build_object('data',jsonb_build_object('callId',(d->>'call_id')::numeric,'language',d->'language','callers',d->'callers','segments',(select jsonb_agg(x-array['ordinal','text_sha256','projection_from','projection_to']order by ord)from jsonb_array_elements(d->'segments')with ordinality t(x,ord)where ord>(pg->>'offset')::integer and ord<=(pg->>'offset')::integer+(pg->>'count')::integer)),'pagination',jsonb_build_object('limit',pg->'limit','offset',pg->'offset','total',pg->'total'))or jsonb_typeof(pg->'retrieved_at')is distinct from'string'or(pg->>'retrieved_at')::timestamptz not between(d->>'captured_from')::timestamptz and(d->>'captured_until')::timestamptz then raise exception 'Complete bounded page evidence required'using errcode='PT422';end if;expected_offset:=expected_offset+(pg->>'count')::integer;
  end loop;
  if expected_offset<>n or page_count not between 1 and 10 then raise exception 'Incomplete enumeration'using errcode='PT422';end if;
 end loop;
 if exists(select 1 from jsonb_array_elements(d->'pages')a where(a->>'pass')::integer=1 and not exists(select 1 from jsonb_array_elements(d->'pages')b where(b->>'pass')::integer=2 and a->'offset'=b->'offset'and a->'sha256'=b->'sha256'))then raise exception 'Observed passes differ'using errcode='PT422';end if;
end $$;
create function public.finish_clinical_call_capture(p_id uuid,p_document jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare a clinical_call_capture_actions;s clinical_call_sources;h text;begin
 perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));select *into a from clinical_call_capture_actions where id=p_id for update;if not found then raise exception 'Capture missing'using errcode='PT404';end if;
 h:=public.clinical_recap_hash(p_document);if a.result_hash is not null then if a.result_hash is distinct from h then raise exception 'Result conflict'using errcode='PT409';end if;return jsonb_build_object('capture_id',p_id,'source_id',a.source_id,'retained',a.state='completed');end if;
 if a.state<>'capturing'or a.lease_until is null or a.lease_until<=clock_timestamp()then raise exception 'Capture lease expired or not dispatched'using errcode='PT409';end if;perform public.clinical_call_capture_guard(a);if a.lease_until is null or a.lease_until<=clock_timestamp()then raise exception 'Capture expired during source wait'using errcode='PT409';end if;
 perform public.clinical_call_validate_document(p_document,a.binding->>'call_id');
 insert into clinical_call_sources(id,capture_id,actor_id,pet_id,encounter_id,client_id,conversation_id,call_uuid,call_id,policy_version,context,document,sha256)values(p_id,p_id,a.actor_id,(a.request->>'pet_id')::uuid,(a.request->>'encounter_id')::uuid,(a.binding->>'client_id')::uuid,(a.binding->>'conversation_id')::uuid,a.binding->>'call_uuid',a.binding->>'call_id',(a.request->>'policy_version')::integer,a.binding,p_document,public.clinical_recap_hash(jsonb_build_object('context',a.binding,'document',p_document)))returning *into s;
 update clinical_call_capture_actions set state='completed',source_id=s.id,result_hash=h,finished_at=clock_timestamp()where id=p_id;return jsonb_build_object('capture_id',p_id,'source_id',s.id,'retained',true);end $$;
create function public.fail_clinical_call_capture(p_id uuid,p_code text)returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 if p_code is null or p_code not in('provider_body_invalid','provider_budget_exceeded','provider_response_invalid','provider_pagination_changed','provider_source_changed','provider_pagination_incomplete','provider_segment_order_invalid','dispatch_invalid','capture_unconfirmed')then raise exception 'Sanitized capture error required'using errcode='PT422';end if;
 perform pg_advisory_xact_lock(hashtextextended('clinical-call-policy',0));perform pg_advisory_xact_lock(hashtextextended('clinical-call-action:'||p_id,0));update clinical_call_capture_actions set state='failed',error_code=p_code,finished_at=clock_timestamp()where id=p_id and state='capturing';end $$;
create function public.list_clinical_call_candidates(p_actor_id uuid,p_pet_id uuid,p_encounter_id uuid,p_expected_version integer)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare patient pets;enc clinical_encounters;items jsonb;begin
 perform public.clinical_call_actor(p_actor_id);select *into enc from clinical_encounters where id=p_encounter_id for share;select *into patient from pets where id=p_pet_id for share;if p_expected_version is null or p_expected_version not between 1 and 2147483646 or patient.id is null or enc.id is null or enc.pet_id<>patient.id or enc.version is distinct from p_expected_version or enc.status<>'draft'or patient.archived_at is not null or patient.deceased_at is not null then raise exception 'Exact active patient and unsigned destination required'using errcode='PT409';end if;
 select coalesce(jsonb_agg(to_jsonb(t)order by t.occurred_at desc,t.inbound_id desc),'[]'::jsonb)into items from(select i.id inbound_id,i.version inbound_version,c.call_uuid,c.call_id,i.occurred_at,i.client_id,i.conversation_id from communication_inbound i join cloudtalk_calls c on i.resource_id='call:'||c.call_uuid join conversations thread on thread.id=i.conversation_id and thread.client_id=i.client_id join messages m on m.id=i.message_id and m.conversation_id=i.conversation_id and m.provider='cloudtalk'and m.provider_message_id=i.resource_id where i.provider='cloudtalk'and i.client_id=patient.client_id and c.ended_at is not null and c.trusted_number and c.transcript_ready and c.call_id~'^[1-9][0-9]{0,15}$'and c.call_id::numeric<=9007199254740991 order by i.occurred_at desc,i.id desc limit 101)t;perform public.clinical_call_actor(p_actor_id);return jsonb_build_object('policy',public.clinical_call_current_policy(),'calls',(select coalesce(jsonb_agg(value order by n),'[]'::jsonb)from jsonb_array_elements(items)with ordinality t(value,n)where n<=100),'has_more',jsonb_array_length(items)>100);end $$;
create function public.read_clinical_call_source(p_actor_id uuid,p_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s clinical_call_sources;begin perform public.clinical_call_actor(p_actor_id);select *into s from clinical_call_sources where id=p_id;if not found then raise exception 'Source missing'using errcode='PT404';end if;perform public.clinical_call_source_access(s);perform public.clinical_call_actor(p_actor_id);return to_jsonb(s);end $$;
create function public.list_clinical_call_sources(p_actor_id uuid,p_pet_id uuid)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare s clinical_call_sources;items jsonb:='[]';total integer:=0;begin perform public.clinical_call_actor(p_actor_id);for s in select retained.*from clinical_call_sources retained join pets p on p.id=retained.pet_id and p.client_id=retained.client_id join cloudtalk_calls provider on provider.call_uuid=retained.call_uuid and provider.call_id=retained.call_id and provider.trusted_number join communication_inbound i on i.provider='cloudtalk'and i.resource_id='call:'||retained.call_uuid and i.client_id=retained.client_id and i.conversation_id=retained.conversation_id join conversations c on c.id=i.conversation_id and c.client_id=i.client_id join messages m on m.id=i.message_id and m.conversation_id=c.id and m.provider='cloudtalk'and m.provider_message_id=i.resource_id where retained.pet_id=p_pet_id order by retained.created_at desc,retained.id desc limit 101 loop total:=total+1;if total<=100 then perform public.clinical_call_source_access(s);items:=items||jsonb_build_array(to_jsonb(s)-'document');end if;end loop;perform public.clinical_call_actor(p_actor_id);return jsonb_build_object('sources',items,'has_more',total>100);end $$;
do $$declare f record;begin for f in select oid,proname from pg_proc where pronamespace='public'::regnamespace and(proname like'clinical_call_%'or proname in('read_clinical_call_policy','save_clinical_call_policy','recover_clinical_call_policy','cancel_clinical_call_policy','list_clinical_call_candidates','reserve_clinical_call_capture','read_clinical_call_capture','cancel_clinical_call_capture','dispatch_clinical_call_capture','finish_clinical_call_capture','fail_clinical_call_capture','list_clinical_call_sources','read_clinical_call_source'))loop
 execute format('revoke all on function %s from public,anon,authenticated,service_role',f.oid::regprocedure);
 if f.proname in('read_clinical_call_policy','save_clinical_call_policy','recover_clinical_call_policy','cancel_clinical_call_policy','list_clinical_call_candidates','reserve_clinical_call_capture','read_clinical_call_capture','cancel_clinical_call_capture','list_clinical_call_sources','read_clinical_call_source')then execute format('grant execute on function %s to authenticated',f.oid::regprocedure);end if;
 if f.proname in('dispatch_clinical_call_capture','finish_clinical_call_capture','fail_clinical_call_capture')then execute format('grant execute on function %s to service_role',f.oid::regprocedure);end if;end loop;end $$;
